g = [[8]*14 for _ in range(18)]
seed = [[8,8,8,1,7],[8,1,0,0,1],[7,0,1,1,7]]
for dr,row in enumerate(seed):
    for dc,v in enumerate(row):
        g[2+dr][8+dc]=v
markers=[(2,4),(7,3),(9,8),(11,2),(16,3),(16,9)]
for r,c in markers:g[r][c]=3
# Reproduce non-background seed pixels around its center (row 3, col 10).
for r,c in markers:
    for dr in range(-1,2):
        for dc in range(-2,3):
            v=seed[dr+1][dc+2]
            if v != 8:
                rr,cc=r+dr,c+dc
                if 0 <= rr < 18 and 0 <= cc < 14:
                    g[rr][cc]=v
print(len(g), [len(row) for row in g])
print('\n'.join(' '.join(map(str,row)) for row in g))

g = [[8]*14 for _ in range(18)]
seed = [[8,8,8,1,7],[8,1,0,0,1],[7,0,1,1,7]]
# Preserve the embedded stencil at rows 2-4, columns 8-12.
for dr in range(3):
    for dc in range(5): g[2+dr][8+dc]=seed[dr][dc]
markers=[(2,4),(7,3),(9,8),(11,2),(16,3),(16,9)]
for r,c in markers:g[r][c]=3
for r,c in markers:
    for dr in range(3):
        for dc in range(5):
            v=seed[dr][dc]
            if v != 8:
                rr,cc=r+dr-1,c+dc-2
                if 0 <= rr < 18 and 0 <= cc < 14: g[rr][cc]=v
print('\n'.join('['+', '.join(map(str,row))+'],' for row in g))
print('dimensions',len(g),set(map(len,g)))

